package app.itemstotext;

import java.time.Instant;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import net.runelite.api.GrandExchangeOfferState;

final class ItemsState
{
	static final class ItemEntry
	{
		final String name;
		final long quantity;

		ItemEntry(String name, long quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}

	static final class OfferEntry
	{
		final int slot;
		final String itemName;
		final int price;
		final int totalQuantity;
		final int completedQuantity;
		final GrandExchangeOfferState state;

		OfferEntry(int slot, String itemName, int price, int totalQuantity,
			int completedQuantity, GrandExchangeOfferState state)
		{
			this.slot = slot;
			this.itemName = itemName;
			this.price = price;
			this.totalQuantity = totalQuantity;
			this.completedQuantity = completedQuantity;
			this.state = state;
		}
	}

	final Instant capturedAt;
	final boolean inventorySpecified;
	final boolean equipmentSpecified;
	final boolean bankSpecified;
	final boolean grandExchangeSpecified;
	final List<ItemEntry> inventory;
	final List<ItemEntry> equipment;
	final List<ItemEntry> bank;
	final List<OfferEntry> offers;

	ItemsState(Instant capturedAt, boolean inventorySpecified, boolean equipmentSpecified,
		boolean bankSpecified, boolean grandExchangeSpecified, List<ItemEntry> inventory,
		List<ItemEntry> equipment, List<ItemEntry> bank, List<OfferEntry> offers)
	{
		this.capturedAt = capturedAt;
		this.inventorySpecified = inventorySpecified;
		this.equipmentSpecified = equipmentSpecified;
		this.bankSpecified = bankSpecified;
		this.grandExchangeSpecified = grandExchangeSpecified;
		this.inventory = immutableCopy(inventory);
		this.equipment = immutableCopy(equipment);
		this.bank = immutableCopy(bank);
		this.offers = immutableCopy(offers);
	}

	private static <T> List<T> immutableCopy(List<T> values)
	{
		return Collections.unmodifiableList(new ArrayList<>(values));
	}
}

package app.itemstotext;

import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Locale;
import net.runelite.api.GrandExchangeOfferState;

final class ItemsTextFormatter
{
	private static final DateTimeFormatter DISPLAY_TIME = DateTimeFormatter
		.ofPattern("MMM d, yyyy 'at' h:mm a")
		.withLocale(Locale.ENGLISH)
		.withZone(ZoneId.systemDefault());

	private ItemsTextFormatter()
	{
	}

	static String format(ItemsState state)
	{
		StringBuilder text = new StringBuilder(512 + state.bank.size() * 24);
		text.append("Items to Text\n")
			.append("Captured: ").append(DISPLAY_TIME.format(state.capturedAt)).append("\n\n");
		appendItems(text, "Inventory", state.inventorySpecified, state.inventory);
		appendItems(text, "Equipment", state.equipmentSpecified, state.equipment);
		appendItems(text, "Bank", state.bankSpecified, state.bank);
		appendOffers(text, state.grandExchangeSpecified, state.offers);
		return text.toString().trim() + "\n";
	}

	private static void appendItems(StringBuilder text, String heading, boolean specified,
		List<ItemsState.ItemEntry> items)
	{
		text.append(heading).append(":\n");
		if (!specified)
		{
			text.append("Unspecified\n\n");
			return;
		}
		if (items.isEmpty())
		{
			text.append("Empty\n\n");
			return;
		}

		List<ItemsState.ItemEntry> sorted = new ArrayList<>(items);
		sorted.sort(Comparator.comparing((ItemsState.ItemEntry item) -> item.name, String.CASE_INSENSITIVE_ORDER));
		for (ItemsState.ItemEntry item : sorted)
		{
			text.append(clean(item.name)).append(' ').append(number(item.quantity)).append('\n');
		}
		text.append('\n');
	}

	private static void appendOffers(StringBuilder text, boolean specified, List<ItemsState.OfferEntry> offers)
	{
		text.append("Grand Exchange:\n");
		if (!specified)
		{
			text.append("Unspecified\n");
			return;
		}
		for (int slot = 0; slot < 8; slot++)
		{
			ItemsState.OfferEntry offer = findOffer(offers, slot);
			text.append("Slot ").append(slot + 1).append(": ");
			if (offer == null || offer.state == GrandExchangeOfferState.EMPTY)
			{
				text.append("Empty\n");
				continue;
			}
			text.append(status(offer.state)).append(' ').append(clean(offer.itemName)).append(' ')
				.append(number(offer.completedQuantity)).append(" of ")
				.append(number(offer.totalQuantity)).append(" at ")
				.append(number(offer.price)).append(" gp\n");
		}
	}

	private static ItemsState.OfferEntry findOffer(List<ItemsState.OfferEntry> offers, int slot)
	{
		for (ItemsState.OfferEntry offer : offers)
		{
			if (offer.slot == slot)
			{
				return offer;
			}
		}
		return null;
	}

	private static String status(GrandExchangeOfferState state)
	{
		switch (state)
		{
			case BUYING: return "Buying";
			case BOUGHT: return "Bought";
			case SELLING: return "Selling";
			case SOLD: return "Sold";
			case CANCELLED_BUY: return "Cancelled buy";
			case CANCELLED_SELL: return "Cancelled sell";
			default: return "Empty";
		}
	}

	private static String number(long value)
	{
		return String.format(Locale.US, "%,d", value);
	}

	private static String clean(String value)
	{
		return value.replace('\n', ' ').replace('\r', ' ').trim();
	}
}

package app.itemstotext;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Font;
import java.awt.Toolkit;
import java.awt.datatransfer.StringSelection;
import javax.swing.BorderFactory;
import javax.swing.JButton;
import javax.swing.JLabel;
import javax.swing.JScrollPane;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.border.EmptyBorder;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

final class ItemsToTextPanel extends PluginPanel
{
	private final JLabel status = new JLabel("Waiting for account items…");
	private final JTextArea itemText = new JTextArea();
	private final JButton copyButton = new JButton("Copy items");

	ItemsToTextPanel()
	{
		super(false);
		setLayout(new BorderLayout(0, 8));
		setBorder(new EmptyBorder(10, 10, 10, 10));
		setBackground(ColorScheme.DARK_GRAY_COLOR);

		status.setForeground(Color.LIGHT_GRAY);
		status.setBorder(new EmptyBorder(0, 1, 0, 0));
		add(status, BorderLayout.NORTH);

		itemText.setEditable(false);
		itemText.setLineWrap(false);
		itemText.setFont(new Font(Font.MONOSPACED, Font.PLAIN, 11));
		itemText.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		itemText.setForeground(Color.WHITE);
		itemText.setBorder(new EmptyBorder(8, 8, 8, 8));
		itemText.setText("Items to Text\n\nInventory:\nUnspecified\n\nEquipment:\nUnspecified\n\nBank:\nUnspecified\n\nGrand Exchange:\nUnspecified");
		JScrollPane scrollPane = new JScrollPane(itemText);
		scrollPane.setBorder(BorderFactory.createLineBorder(ColorScheme.MEDIUM_GRAY_COLOR));
		add(scrollPane, BorderLayout.CENTER);

		copyButton.setEnabled(false);
		copyButton.addActionListener(event -> copyItems());
		add(copyButton, BorderLayout.SOUTH);
	}

	void setText(String text)
	{
		SwingUtilities.invokeLater(() ->
		{
			itemText.setText(text);
			itemText.setCaretPosition(0);
			status.setText("Current item view");
			copyButton.setEnabled(true);
		});
	}

	private void copyItems()
	{
		Toolkit.getDefaultToolkit().getSystemClipboard()
			.setContents(new StringSelection(itemText.getText()), null);
		status.setText("Items copied");
	}
}

package app.itemstotext;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.time.Instant;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "Items to Text",
	description = "Shows your items as a simple readable list you can copy",
	tags = {"items", "text", "bank", "inventory", "equipment", "grand exchange", "copy"}
)
public class ItemsToTextPlugin extends Plugin
{
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar clientToolbar;
	@Inject private ItemManager itemManager;

	private final Map<Integer, String> itemNames = new HashMap<>();
	private List<ItemsState.ItemEntry> inventory = new ArrayList<>();
	private List<ItemsState.ItemEntry> equipment = new ArrayList<>();
	private List<ItemsState.ItemEntry> bank = new ArrayList<>();
	private final Map<Integer, ItemsState.OfferEntry> offers = new HashMap<>();
	private boolean inventorySpecified;
	private boolean equipmentSpecified;
	private boolean bankSpecified;
	private boolean grandExchangeSpecified;
	private ItemsToTextPanel panel;
	private NavigationButton navigationButton;

	@Override
	protected void startUp()
	{
		panel = new ItemsToTextPanel();
		navigationButton = NavigationButton.builder()
			.tooltip("Items to Text")
			.icon(createSidebarIcon())
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navigationButton);
		clientThread.invokeLater(this::refreshVisibleContainers);
		log.debug("Items to Text started");
	}

	@Override
	protected void shutDown()
	{
		if (navigationButton != null)
		{
			clientToolbar.removeNavigation(navigationButton);
		}
		itemNames.clear();
		inventory.clear();
		equipment.clear();
		bank.clear();
		offers.clear();
		inventorySpecified = false;
		equipmentSpecified = false;
		bankSpecified = false;
		grandExchangeSpecified = false;
		navigationButton = null;
		panel = null;
		log.debug("Items to Text stopped");
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (panel == null) return;
		if (event.getContainerId() == InventoryID.INV)
		{
			inventory = snapshotItems(event.getItemContainer());
			inventorySpecified = true;
		}
		else if (event.getContainerId() == InventoryID.WORN)
		{
			equipment = snapshotItems(event.getItemContainer());
			equipmentSpecified = true;
		}
		else if (event.getContainerId() == InventoryID.BANK)
		{
			bank = snapshotItems(event.getItemContainer());
			bankSpecified = true;
		}
		else return;
		publishText();
	}

	@Subscribe
	public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
	{
		if (panel == null) return;
		offers.put(event.getSlot(), snapshotOffer(event.getSlot(), event.getOffer()));
		if (event.getOffer() != null && event.getOffer().getState() != GrandExchangeOfferState.EMPTY)
		{
			grandExchangeSpecified = true;
		}
		publishText();
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (!isGrandExchangeInterface(event.getGroupId())) return;
		grandExchangeSpecified = true;
		refreshOffers();
		publishText();
	}

	static boolean isGrandExchangeInterface(int groupId)
	{
		return groupId == InterfaceID.GE_OFFERS
			|| groupId == InterfaceID.GE_OFFERS_SIDE
			|| groupId == InterfaceID.GE_COLLECT;
	}

	private void refreshVisibleContainers()
	{
		ItemContainer inventoryContainer = client.getItemContainer(InventoryID.INV);
		ItemContainer equipmentContainer = client.getItemContainer(InventoryID.WORN);
		ItemContainer bankContainer = client.getItemContainer(InventoryID.BANK);
		if (inventoryContainer != null)
		{
			inventory = snapshotItems(inventoryContainer);
			inventorySpecified = true;
		}
		if (equipmentContainer != null)
		{
			equipment = snapshotItems(equipmentContainer);
			equipmentSpecified = true;
		}
		if (bankContainer != null)
		{
			bank = snapshotItems(bankContainer);
			bankSpecified = true;
		}
		refreshOffers();
		publishText();
	}

	private void refreshOffers()
	{
		GrandExchangeOffer[] currentOffers = client.getGrandExchangeOffers();
		if (currentOffers == null) return;
		for (int slot = 0; slot < currentOffers.length; slot++)
		{
			offers.put(slot, snapshotOffer(slot, currentOffers[slot]));
		}
	}

	private List<ItemsState.ItemEntry> snapshotItems(ItemContainer container)
	{
		Map<String, Long> quantities = new TreeMap<>(String.CASE_INSENSITIVE_ORDER);
		for (Item item : container.getItems())
		{
			if (item.getId() <= 0 || item.getQuantity() <= 0) continue;
			quantities.merge(itemName(item.getId()), (long) item.getQuantity(), Long::sum);
		}
		List<ItemsState.ItemEntry> snapshot = new ArrayList<>();
		quantities.forEach((name, quantity) -> snapshot.add(new ItemsState.ItemEntry(name, quantity)));
		return snapshot;
	}

	private ItemsState.OfferEntry snapshotOffer(int slot, GrandExchangeOffer offer)
	{
		GrandExchangeOfferState state = offer == null ? GrandExchangeOfferState.EMPTY : offer.getState();
		int itemId = offer == null ? -1 : offer.getItemId();
		return new ItemsState.OfferEntry(slot, itemId > 0 ? itemName(itemId) : "Empty",
			offer == null ? 0 : offer.getPrice(), offer == null ? 0 : offer.getTotalQuantity(),
			offer == null ? 0 : offer.getQuantitySold(), state);
	}

	private String itemName(int itemId)
	{
		return itemNames.computeIfAbsent(itemId, id ->
		{
			String name = itemManager.getItemComposition(id).getName();
			return name == null || name.trim().isEmpty() ? "Unknown item" : name;
		});
	}

	private void publishText()
	{
		if (panel == null) return;
		panel.setText(ItemsTextFormatter.format(new ItemsState(Instant.now(), inventorySpecified,
			equipmentSpecified, bankSpecified, grandExchangeSpecified, inventory, equipment, bank,
			new ArrayList<>(offers.values()))));
	}

	private static BufferedImage createSidebarIcon()
	{
		BufferedImage image = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
		Graphics2D graphics = image.createGraphics();
		graphics.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		graphics.setStroke(new BasicStroke(2.25f));
		graphics.setColor(new Color(31, 34, 38));
		graphics.fillRoundRect(5, 3, 22, 27, 4, 4);
		graphics.setColor(new Color(218, 161, 61));
		graphics.drawRoundRect(5, 3, 21, 26, 4, 4);
		graphics.setColor(new Color(245, 213, 139));
		graphics.drawLine(10, 10, 22, 10);
		graphics.drawLine(10, 16, 22, 16);
		graphics.drawLine(10, 22, 19, 22);
		graphics.dispose();
		return image;
	}
}

package app.itemstotext;

import java.time.Instant;
import java.util.Arrays;
import java.util.Collections;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertTrue;

public class ItemsTextFormatterTest
{
	@Test
	public void buildsReadableNameOnlyList()
	{
		ItemsState state = new ItemsState(
			Instant.parse("2026-07-23T12:00:00Z"), true, true, false, true,
			Arrays.asList(new ItemsState.ItemEntry("Shark", 12), new ItemsState.ItemEntry("Coins", 125000)),
			Collections.singletonList(new ItemsState.ItemEntry("Abyssal whip", 1)),
			Collections.emptyList(),
			Collections.singletonList(new ItemsState.OfferEntry(0, "Abyssal whip", 1650000, 8, 3,
				GrandExchangeOfferState.BUYING)));

		String text = ItemsTextFormatter.format(state);
		assertTrue(text.startsWith("Items to Text\nCaptured: "));
		assertTrue(text.contains("Inventory:\nCoins 125,000\nShark 12"));
		assertTrue(text.contains("Equipment:\nAbyssal whip 1"));
		assertTrue(text.contains("Bank:\nUnspecified"));
		assertTrue(text.contains("Grand Exchange:\nSlot 1: Buying Abyssal whip 3 of 8 at 1,650,000 gp"));
		assertTrue(!text.matches("(?s).*\\b4151\\b.*"));
	}
}

package app.itemstotext;

import net.runelite.api.gameval.InterfaceID;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ItemsToTextPluginLogicTest
{
	@Test
	public void recognizesEveryGrandExchangeView()
	{
		assertTrue(ItemsToTextPlugin.isGrandExchangeInterface(InterfaceID.GE_OFFERS));
		assertTrue(ItemsToTextPlugin.isGrandExchangeInterface(InterfaceID.GE_OFFERS_SIDE));
		assertTrue(ItemsToTextPlugin.isGrandExchangeInterface(InterfaceID.GE_COLLECT));
		assertFalse(ItemsToTextPlugin.isGrandExchangeInterface(InterfaceID.BANKMAIN));
	}
}

